INSERT INTO "works" VALUES('W2588528173','https://doi.org/10.1016/j.clinph.2016.10.219','P094 Method for EEG guided transcranial Electrical Stimulation without models','p094 method for eeg guided transcranial electrical stimulation without models','conference-abstract','2017-02-15',2017,'Clinical Neurophysiology',NULL,'https://doi.org/10.1016/j.clinph.2016.10.219',NULL,0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Andrea Cancelli", "id": "A5090928057"}, {"name": "Carlo Cottone", "id": "A5074984501"}, {"name": "Franca Tecchio", "id": "A5047252819"}, {"name": "Dennis Q. Truong", "id": "A5057783947"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Devin Adair", "id": "A5035340679"}, {"name": "Marom Bikson", "id": "A5025915090"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2588643847','https://doi.org/10.1016/j.brs.2017.01.278','Modulation of physiologic artifacts during concurrent tDCS and EEG','modulation of physiologic artifacts during concurrent tdcs and eeg','article','2017-02-15',2017,'Brain stimulation',NULL,'https://doi.org/10.1016/j.brs.2017.01.278','https://doaj.org/article/cca1454e338a43ab80d2d7c9c8d4aaca',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Nigel Gebodh", "id": "A5076155222"}, {"name": "Devin Adair", "id": "A5035340679"}, {"name": "Kenneth C. Chelette", "id": "A5018194134"}, {"name": "Zeinab Esmaeilpour", "id": "A5102714296"}, {"name": "Marom Bikson", "id": "A5025915090"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Lucas C. Parra", "id": "A5079902276"}, {"name": "Adam J. Woods", "id": "A5061473412"}, {"name": "Emily S. Kappenman", "id": "A5009102481"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2568518699','https://doi.org/10.1038/srep43916','EEG in the classroom: Synchronised neural recordings during video presentation','eeg in the classroom synchronised neural recordings during video presentation','article','2017-03-07',2017,'Scientific Reports','We performed simultaneous recordings of electroencephalography (EEG) from multiple students in a classroom, and measured the inter-subject correlation (ISC) of activity evoked by a common video stimulus. The neural reliability, as quantified by ISC, has been linked to engagement and attentional modulation in earlier studies that used high-grade equipment in laboratory settings. Here we reproduce many of the results from these studies using portable low-cost equipment, focusing on the robustness of using ISC for subjects experiencing naturalistic stimuli. The present data shows that stimulus-evoked neural responses, known to be modulated by attention, can be tracked for groups of students with synchronized EEG acquisition. This is a step towards real-time inference of engagement in the classroom.','https://doi.org/10.1038/srep43916','https://www.nature.com/articles/srep43916.pdf',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Andreas Trier Poulsen", "id": "A5049207324"}, {"name": "Simon Kamronn", "id": "A5015747771"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Lucas C. Parra", "id": "A5079902276"}, {"name": "Lars Kai Hansen", "id": "A5018292103"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2618266383','https://doi.org/10.1016/j.neuroimage.2017.05.037','Extracting multidimensional stimulus-response correlations using hybrid encoding-decoding of neural activity','extracting multidimensional stimulus response correlations using hybrid encoding decoding of neural activity','article','2017-05-22',2017,'NeuroImage','In neuroscience, stimulus-response relationships have traditionally been analyzed using either encoding or decoding models. Here we propose a hybrid approach that decomposes neural activity into multiple components, each representing a portion of the stimulus. The technique is implemented via canonical correlation analysis (CCA) by temporally filtering the stimulus (encoding) and spatially filtering the neural responses (decoding) such that the resulting components are maximally correlated. In contrast to existing methods, this approach recovers multiple correlated stimulus-response pairs, and thus affords a richer, multidimensional analysis of neural representations. We first validated the technique''s ability to recover multiple stimulus-driven components using electroencephalographic (EEG) data simulated with a finite element model of the head. We then applied the technique to real EEG responses to auditory and audiovisual narratives experienced identically across subjects, as well as uniquely experienced video game play. During narratives, both auditory and visual stimulus-response correlations (SRC) were modulated by attention and tracked inter-subject correlations. During video game play, SRC varied with game difficulty and the presence of a dual task. Interestingly, the strongest component extracted for visual and auditory features of film clips had nearly identical spatial distributions, suggesting that the predominant encephalographic response to naturalistic stimuli is supramodal. The diversity of these findings demonstrates the utility of measuring multidimensional SRC via hybrid encoding-decoding.','https://doi.org/10.1016/j.neuroimage.2017.05.037','https://www.sciencedirect.com/science/article/pii/S1053811917304299/pdf',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Jason J. Ki", "id": "A5025681136"}, {"name": "Paul DeGuzman", "id": "A5090199132"}, {"name": "Paul Sajda", "id": "A5042749874"}, {"name": "Lucas C. Parra", "id": "A5079902276"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2621197457','https://doi.org/10.1016/j.cell.2017.05.017','Noninvasive Neuromodulation Goes Deep','noninvasive neuromodulation goes deep','article','2017-06-01',2017,'Cell',NULL,'https://doi.org/10.1016/j.cell.2017.05.017','http://www.cell.com/article/S0092867417305779/pdf',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Marom Bikson", "id": "A5025915090"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2949119193','https://doi.org/10.1016/j.neuroimage.2017.05.059','Optimal use of EEG recordings to target active brain areas with transcranial electrical stimulation','optimal use of eeg recordings to target active brain areas with transcranial electrical stimulation','article','2017-06-01',2017,'NeuroImage','To demonstrate causal relationships between brain and behavior, investigators would like to guide brain stimulation using measurements of neural activity. Particularly promising in this context are electroencephalography (EEG) and transcranial electrical stimulation (TES), as they are linked by a reciprocity principle which, despite being known for decades, has not led to a formalism for relating EEG recordings to optimal stimulation parameters. Here we derive a closed-form expression for the TES configuration that optimally stimulates (i.e., targets) the sources of recorded EEG, without making assumptions about source location or distribution. We also derive a duality between TES targeting and EEG source localization, and demonstrate that in cases where source localization fails, so does the proposed targeting. Numerical simulations with multiple head models confirm these theoretical predictions and quantify the achieved stimulation in terms of focality and intensity. We show that constraining the stimulation currents automatically selects optimal montages that involve only a few (4-7) electrodes, with only incremental loss in performance when targeting focal activations. The proposed technique allows brain scientists and clinicians to rationally target the sources of observed EEG and thus overcomes a major obstacle to the realization of individualized or closed-loop brain stimulation.','https://doi.org/10.1016/j.neuroimage.2017.05.059','https://doi.org/10.1016/j.neuroimage.2017.05.059',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Laurent Koessler", "id": "A5044901102"}, {"name": "Anthony M. Norcia", "id": "A5046794552"}, {"name": "Marom Bikson", "id": "A5025915090"}, {"name": "Lucas C. Parra", "id": "A5079902276"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
