INSERT INTO "works" VALUES('W2778005188','https://doi.org/10.1016/j.brs.2017.12.008','Rigor and reproducibility in research with transcranial electrical stimulation: An NIMH-sponsored workshop','rigor and reproducibility in research with transcranial electrical stimulation an nimh sponsored workshop','article','2017-12-29',2017,'Brain stimulation','BACKGROUND: Neuropsychiatric disorders are a leading source of disability and require novel treatments that target mechanisms of disease. As such disorders are thought to result from aberrant neuronal circuit activity, neuromodulation approaches are of increasing interest given their potential for manipulating circuits directly. Low intensity transcranial electrical stimulation (tES) with direct currents (transcranial direct current stimulation, tDCS) or alternating currents (transcranial alternating current stimulation, tACS) represent novel, safe, well-tolerated, and relatively inexpensive putative treatment modalities. OBJECTIVE: This report seeks to promote the science, technology and effective clinical applications of these modalities, identify research challenges, and suggest approaches for addressing these needs in order to achieve rigorous, reproducible findings that can advance clinical treatment. METHODS: The National Institute of Mental Health (NIMH) convened a workshop in September 2016 that brought together experts in basic and human neuroscience, electrical stimulation biophysics and devices, and clinical trial methods to examine the physiological mechanisms underlying tDCS/tACS, technologies and technical strategies for optimizing stimulation protocols, and the state of the science with respect to therapeutic applications and trial designs. RESULTS: Advances in understanding mechanisms, methodological and technological improvements (e.g., electronics, computational models to facilitate proper dosing), and improved clinical trial designs are poised to advance rigorous, reproducible therapeutic applications of these techniques. A number of challenges were identified and meeting participants made recommendations made to address them. CONCLUSIONS: These recommendations align with requirements in NIMH funding opportunity announcements to, among other needs, define dosimetry, demonstrate dose/response relationships, implement rigorous blinded trial designs, employ computational modeling, and demonstrate target engagement when testing stimulation-based interventions for the treatment of mental disorders.','https://doi.org/10.1016/j.brs.2017.12.008','http://www.brainstimjrnl.com/article/S1935861X17310240/pdf',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Marom Bikson", "id": "A5025915090"}, {"name": "André R. Brunoni", "id": "A5063506824"}, {"name": "Leigh Elkins Charvet", "id": "A5034190131"}, {"name": "Vincent P. Clark", "id": "A5085419608"}, {"name": "Leonardo G. Cohen", "id": "A5050316387"}, {"name": "Zhi‐De Deng", "id": "A5021455956"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Dylan J. Edwards", "id": "A5081308782"}, {"name": "Flavio Frӧhlich", "id": "A5064845004"}, {"name": "Emily S. Kappenman", "id": "A5009102481"}, {"name": "Kelvin O. Lim", "id": "A5043671103"}, {"name": "Colleen K A Loo", "id": "A5003963348"}, {"name": "Antonio Mantovani", "id": "A5111803671"}, {"name": "David P. McMullen", "id": "A5027465876"}, {"name": "Lucas C. Parra", "id": "A5079902276"}, {"name": "Michele Pearson", "id": ""}, {"name": "Jessica D. Richardson", "id": "A5070587797"}, {"name": "Judith M. Rumsey", "id": "A5054825204"}, {"name": "Pejman Sehatpour", "id": "A5037657698"}, {"name": "David Sommers", "id": "A5061950719"}, {"name": "Gozde Unal", "id": ""}, {"name": "Eric M. Wassermann", "id": "A5065615661"}, {"name": "Adam J. Woods", "id": "A5061473412"}, {"name": "Sarah Hollingsworth Lisanby", "id": "A5049234393"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2902367809','https://doi.org/10.1364/translational.2018.jth3a.56','Transcranial Laser Stimulation Increases Power of Brain Oscillations and Information Flow Measured by EEG','transcranial laser stimulation increases power of brain oscillations and information flow measured by eeg','conference-paper','2018-01-01',2018,'Optics in the Life Sciences','We conducted placebo-controlled 1064 nm Transcranial Laser Stimulation (TLS) on 20 human foreheads. Significant alterations of EEG power and information flow were observed, indicating important neurophysiological benefits of photoneuromodulation by 1064 nm laser.','https://doi.org/10.1364/translational.2018.jth3a.56',NULL,0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Xinlong Wang", "id": "A5100653838"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Francisco Gonzalez-Lima", "id": "A5011542591"}, {"name": "Hanli Liu", "id": "A5100667053"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W4310746865','https://doi.org/10.51628/001c.7125','Correlated Components Analysis - Extracting Reliable Dimensions in Multivariate Data','correlated components analysis extracting reliable dimensions in multivariate data','preprint','2018-01-26',2018,'arXiv (Cornell University)','How does one find dimensions in multivariate data that are reliably expressed across repetitions? For example, in a brain imaging study one may want to identify combinations of neural signals that are reliably expressed across multiple trials or subjects. For a behavioral assessment with multiple ratings, one may want to identify an aggregate score that is reliably reproduced across raters. Correlated Components Analysis (CorrCA) addresses this problem by identifying components that are maximally correlated between repetitions (e.g. trials, subjects, raters). Here we formalize this as the maximization of the ratio of between-repetition to within-repetition covariance. We show that this criterion maximizes repeat-reliability, defined as mean over variance across repeats, and that it leads to CorrCA or to multi-set Canonical Correlation Analysis, depending on the constraints. Surprisingly, we also find that CorrCA is equivalent to Linear Discriminant Analysis for zero-mean signals, which provides an unexpected link between classic concepts of multivariate analysis. We present an exact parametric test of statistical significance based on the F-statistic for normally distributed independent samples, and present and validate shuffle statistics for the case of dependent samples. Regularization and extension to non-linear mappings using kernels are also presented. The algorithms are demonstrated on a series of data analysis applications, and we provide all code and data required to reproduce the results.','http://arxiv.org/abs/1801.08881','https://arxiv.org/pdf/1801.08881',0,'2022-12-17T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Lucas C. Parra", "id": "A5079902276"}, {"name": "Stefan Haufe", "id": "A5068256213"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2790422932','https://doi.org/10.1016/j.neuroimage.2018.03.035','Correlation of neural activity with behavioral kinematics reveals distinct sensory encoding and evidence accumulation processes during active tactile sensing','correlation of neural activity with behavioral kinematics reveals distinct sensory encoding and evidence accumulation processes during active tactile sensing','article','2018-03-23',2018,'NeuroImage',NULL,'https://doi.org/10.1016/j.neuroimage.2018.03.035','https://doi.org/10.1016/j.neuroimage.2018.03.035',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Ioannis Delis", "id": "A5009314634"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Paul Sajda", "id": "A5042749874"}, {"name": "Qi Wang", "id": "A5086647896"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2878118375','https://doi.org/10.1145/3200947.3201027','Correlations of Neural Activity with Behavioral Kinematics during Active Tactile Decision Making','correlations of neural activity with behavioral kinematics during active tactile decision making','conference-paper','2018-07-06',2018,'Hellenic Conference on Artificial Intelligence','Most real-world decisions rely on active sensing, a dynamic process for directing our sensors (e.g. eyes or fingers) across a stimulus in order to reduce uncertainty and maximize information gain. Though ecologically pervasive, relatively limited work has focused on identifying neural correlates of the active sensing process. In tactile perception, we often make decisions about an object or surface by actively exploring its shape and texture. Here we investigate the neural mechanisms of active tactile sensing by simultaneously measuring electroencephalography (EEG) and finger kinematics while subjects interrogated a haptic surface to make perceptual judgements. We hypothesized that one''s sensorimotor behavior provides a view into the cognitive processes leading to decision formation, and the neural correlates of these processes would be detectable by relating kinematics to neural activity. Using an adaptation of canonical correlation analysis (CCA), we regressed the EEG onto kinematics and found three distinct, task-related EEG components that localized to right-lateralized occipital cortex (LOC), middle frontal gyrus (MFG), and supplementary motor area (SMA), respectively. To probe the functional role of these components, we fit their single-trial activity to behavior using a hierarchical drift diffusion model (HDDM), revealing that the LOC modulated the encoding of the tactile stimulus whereas the MFG predicted the rate of information integration towards a choice. This study provides direct evidence that, how we explore the stimulus yields insight into how our brain is forming a decision and uncovers the neural correlates of distinct sensory encoding and evidence accumulation processes during active tactile sensing.','https://doi.org/10.1145/3200947.3201027',NULL,0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Ioannis Delis", "id": "A5009314634"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Paul Sajda", "id": "A5042749874"}, {"name": "Qi Wang", "id": "A5086647896"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W2896984162','https://doi.org/10.1016/j.neuroimage.2018.10.025','Inherent physiological artifacts in EEG during tDCS','inherent physiological artifacts in eeg during tdcs','article','2018-10-12',2018,'NeuroImage',NULL,'https://doi.org/10.1016/j.neuroimage.2018.10.025','https://www.ncbi.nlm.nih.gov/pmc/articles/6289749',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Nigel Gebodh", "id": "A5076155222"}, {"name": "Zeinab Esmaeilpour", "id": "A5001501158"}, {"name": "Devin Adair", "id": "A5035340679"}, {"name": "Kenneth C. Chelette", "id": "A5018194134"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Adam J. Woods", "id": "A5061473412"}, {"name": "Emily S. Kappenman", "id": "A5009102481"}, {"name": "Lucas C. Parra", "id": "A5079902276"}, {"name": "Marom Bikson", "id": "A5025915090"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
