INSERT INTO "works" VALUES('W4320905308','https://doi.org/10.1016/j.brs.2023.01.503','In-vivo Evidence of Substantial Electric Fields in Human Deep Cortical Structures During Transcranial Electrical Stimulations','in vivo evidence of substantial electric fields in human deep cortical structures during transcranial electrical stimulations','article','2023-01-01',2023,'Brain stimulation',NULL,'https://doi.org/10.1016/j.brs.2023.01.503','https://doi.org/10.1016/j.brs.2023.01.503',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Samuel Louviot", "id": "A5045315810"}, {"name": "Louise Tyvaert", "id": "A5032415827"}, {"name": "Louis Georges Maillard", "id": "A5104520775"}, {"name": "Sophie Colnat‐Coulbois", "id": "A5065535915"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Laurent Koessler", "id": "A5044901102"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W7133187552','https://doi.org/10.52202/075280-3415','Granger Components Analysis: Unsupervised learning of latent temporal dependencies','granger components analysis unsupervised learning of latent temporal dependencies','conference-paper','2023-01-01',2023,'neural information processing systems',NULL,'https://doi.org/10.52202/075280-3415',NULL,0,'2026-03-03T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Jacek Dmochowski", "id": "A5067697868"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "works" VALUES('W4316469529','https://doi.org/10.3390/photonics10010090','Grant Report on the Transcranial near Infrared Radiation and Cerebral Blood Flow in Depression (TRIADE) Study','grant report on the transcranial near infrared radiation and cerebral blood flow in depression triade study','article','2023-01-13',2023,'Photonics','We report on the rationale and design of an ongoing National Institute of Mental Health (NIMH) sponsored R61-R33 project in major depressive disorder (MDD). Current treatments for MDD have significant limitations in efficacy and side effect burden. There is a critical need for device-based treatments in MDD that are efficacious, well-tolerated, and easy to use. This project focuses on the adjunctive use of the transcranial photobiomodulation (tPBM) with near-infrared (NIR) light for the treatment of MDD. tPBM with NIR light penetrates robustly into the cerebral cortex, stimulating the mitochondrial respiratory chain, and also significantly increases cerebral blood flow (CBF). In the R61 phase, we will conduct target engagement studies to demonstrate dose-dependent effects of tPBM on the prefrontal cortex (PFC) CBF, using the increase in fMRI blood-oxygenation-level-dependent (BOLD) signal levels as our Go/No-go target engagement biomarker. In the R33 phase, we will conduct a randomized clinical trial of tPBM vs. sham in MDD to establish the target engagement and evaluate the association between changes in the biomarker (BOLD signal) and changes in clinical symptoms, while also collecting important information on antidepressant effects, safety, and tolerability. The study will be done in parallel at New York University/the Nathan Kline Institute (NYU/NKI) and at Massachusetts General Hospital (MGH). The importance of this study is threefold: 1. it targets MDD, a leading cause of disability worldwide, which lacks adequate treatments; 2. it evaluates tPBM, which has a well-established safety profile and has the potential to be safe in at-home administration; and 3. it uses fMRI BOLD changes as a target engagement biomarker. If effects are confirmed, the present study will both support short-term clinical development of an easy to scale device for the treatment of MDD, while also validating a biomarker for the development of future, novel modulation strategies.','https://doi.org/10.3390/photonics10010090','https://www.mdpi.com/2304-6732/10/1/90/pdf?version=1673616577',0,'2025-10-10T00:00:00','2026-10-19T17:27:09+00:00','baseline',NULL,NULL,'[{"name": "Dan Vlad Iosifescu", "id": "A5048498728"}, {"name": "Katherine Anne Collins", "id": "A5083192238"}, {"name": "Aura Maria Hurtado Puerto", "id": "A5090212610"}, {"name": "Molly Irvin", "id": "A5044637065"}, {"name": "Julie A. Clancy", "id": "A5022909248"}, {"name": "Allison Sparpana", "id": "A5029730131"}, {"name": "Elizabeth Sullivan", "id": "A5071834912"}, {"name": "Zamfira Parincu", "id": "A5051427359"}, {"name": "Eva‐Maria Ratai", "id": "A5082365124"}, {"name": "Christopher J. Funes", "id": "A5033096984"}, {"name": "Akila Weerasekera", "id": "A5074425332"}, {"name": "Jacek Dmochowski", "id": "A5067697868"}, {"name": "Paolo Cassano", "id": "A5054406975"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
