BEGIN TRANSACTION;
CREATE TABLE authorships (
    work_id      TEXT NOT NULL REFERENCES works(id),
    faculty_slug TEXT NOT NULL REFERENCES faculty(slug),
    first_seen   TEXT NOT NULL,
    PRIMARY KEY (work_id, faculty_slug)
);
CREATE TABLE faculty (
    slug          TEXT PRIMARY KEY,
    name          TEXT NOT NULL,
    orcid         TEXT,
    scholar       TEXT,
    openalex_ids  TEXT NOT NULL,
    baselined_at  TEXT
);
CREATE TABLE runs (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    started_at  TEXT NOT NULL,
    finished_at TEXT,
    fetched     INTEGER,
    inserted    INTEGER,
    new_count   INTEGER,
    errors      TEXT
);
CREATE TABLE works (
    id               TEXT PRIMARY KEY,
    doi              TEXT,
    title            TEXT,
    title_key        TEXT,
    type             TEXT,
    publication_date TEXT,
    publication_year INTEGER,
    venue            TEXT,
    abstract         TEXT,
    landing_url      TEXT,
    oa_url           TEXT,
    is_retracted     INTEGER NOT NULL DEFAULT 0,
    openalex_created TEXT,
    first_seen       TEXT NOT NULL,
    status           TEXT NOT NULL,
    duplicate_of     TEXT REFERENCES works(id),
    alerted_at       TEXT,
    authors          TEXT,
    review_status    TEXT,
    headline         TEXT,
    summary          TEXT,
    blurb            TEXT,
    blurb_source     TEXT,
    blurb_model      TEXT,
    blurb_at         TEXT,
    pr_number        INTEGER,
    pr_url           TEXT,
    reviewed_at      TEXT
);
CREATE INDEX works_title_key ON works(title_key);
CREATE INDEX works_status ON works(status, alerted_at);
CREATE INDEX works_review ON works(review_status);
DELETE FROM "sqlite_sequence";
COMMIT;
